<script setup lang="ts">
import {onBeforeUnmount,ref,watch} from 'vue';
import AppDialog from './AppDialog.vue';
import CnpjLookup from './CnpjLookup.vue';
const props=defineProps<{id:number|null;request:<T>(path:string,method?:string,body?:unknown)=>Promise<T>}>();
const emit=defineEmits<{close:[];saved:[]}>();
type ContactLink={contato_id:number;nome?:string;funcao:string;receber_email:boolean;tipos:string[]};
type UnionLink={sindicato_id:number;nome?:string;categoria:string;uf:string;municipio:string;principal:boolean;enquadramento_confirmado:boolean};
type Client={razao_social:string;nome_fantasia:string;cnpj:string;uf:string;municipio:string;ativo:boolean;modo_envio:'revisao'|'automatico';contatos:ContactLink[];sindicatos:UnionLink[];dados_cnpj_json?:Record<string,unknown>|null};
const form=ref<Client>({razao_social:'',nome_fantasia:'',cnpj:'',uf:'',municipio:'',ativo:true,modo_envio:'revisao',contatos:[],sindicatos:[]});
const contacts=ref<Array<{id:number;nome:string;email:string}>>([]),unions=ref<Array<{id:number;nome:string}>>([]),loading=ref(true),busy=ref(false),error=ref(''),tab=ref('dados');let alive=true;
const ready=ref(false);
const cadastral=ref<Record<string,unknown>|null|undefined>(undefined);
watch(()=>form.value.cnpj,value=>{if(cadastral.value&&cadastral.value.cnpj!==value.replace(/[^a-z0-9]/gi,'').toUpperCase())cadastral.value=null;});
function applyCnpj(data:Record<string,unknown>){if(busy.value||data.cnpj!==form.value.cnpj.replace(/[^a-z0-9]/gi,'').toUpperCase())return;cadastral.value=data;for(const field of ['razao_social','nome_fantasia','uf','municipio'] as const)form.value[field]=String(data[field]||'');}
const states=['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'];
const types=['Convenção Coletiva','Termo Aditivo de Convenção Coletiva','Acordo Coletivo','Termo Aditivo de Acordo Coletivo','Acordo Coletivo Específico - Programa de Proteção ao Emprego','Acordo Coletivo Específico - Autorização de Trabalho nos Domingos e Feriados','Termo Aditivo de Acordo Coletivo Programa de Proteção ao Emprego','Termo Aditivo de Acordo Coletivo - Autorização de Trabalho nos Domingos e Feriados','Todos os tipos'];
async function initialize(){try{const [people,monitors,detail]=await Promise.all([props.request<Array<{id:number;nome:string;email:string}>>('/api/contexto/contatos'),props.request<Array<{sindicato_id:number;sindicato_nome:string}>>('/api/contexto/monitoramentos'),props.id?props.request<Client>('/api/contexto/clientes/'+props.id):Promise.resolve(null)]);if(!alive)return;contacts.value=people;unions.value=[...new Map(monitors.map(item=>[item.sindicato_id,{id:item.sindicato_id,nome:item.sindicato_nome}])).values()];if(detail){cadastral.value=detail.dados_cnpj_json;form.value={razao_social:detail.razao_social,nome_fantasia:detail.nome_fantasia,cnpj:detail.cnpj,uf:detail.uf,municipio:detail.municipio,ativo:detail.ativo,modo_envio:detail.modo_envio,contatos:detail.contatos.map(item=>({contato_id:item.contato_id,nome:item.nome,funcao:item.funcao,receber_email:item.receber_email,tipos:[...item.tipos]})),sindicatos:detail.sindicatos.map(item=>({...item}))};for(const item of detail.sindicatos)if(!unions.value.some(union=>union.id===item.sindicato_id))unions.value.push({id:item.sindicato_id,nome:item.nome||'Sindicato vinculado'});for(const item of detail.contatos)if(!contacts.value.some(person=>person.id===item.contato_id))contacts.value.push({id:item.contato_id,nome:item.nome||'Contato vinculado',email:''});}}catch(cause){if(alive)error.value=(cause as Error).message;}finally{if(alive)loading.value=false;}}
function toggleContact(id:number,checked:boolean){form.value.contatos=form.value.contatos.filter(item=>item.contato_id!==id);if(checked)form.value.contatos.push({contato_id:id,funcao:'',receber_email:true,tipos:[]});}
function toggleUnion(id:number,checked:boolean){form.value.sindicatos=form.value.sindicatos.filter(item=>item.sindicato_id!==id);if(checked)form.value.sindicatos.push({sindicato_id:id,categoria:'',uf:form.value.uf,municipio:form.value.municipio,principal:false,enquadramento_confirmado:false});}
function principal(id:number){for(const item of form.value.sindicatos)item.principal=item.sindicato_id===id;}
async function save(){if(busy.value||loading.value)return;busy.value=true;error.value='';try{const body={...form.value,...(cadastral.value===undefined?{}:{dados_cnpj:cadastral.value}),contatos:form.value.contatos.map(({nome,...link})=>link),sindicatos:form.value.sindicatos.map(({nome,...link})=>({sindicato_id:link.sindicato_id,categoria:link.categoria,uf:link.uf,municipio:link.municipio,principal:link.principal,enquadramento_confirmado:link.enquadramento_confirmado}))};await props.request('/api/contexto/clientes'+(props.id?'/'+props.id:''),props.id?'PUT':'POST',body);if(alive)emit('saved');}catch(cause){if(alive)error.value=(cause as Error).message;}finally{if(alive)busy.value=false;}}
void initialize().then(()=>{ready.value=!error.value;});onBeforeUnmount(()=>{alive=false;});
</script>
<template>
  <AppDialog :title="id?'Editar cliente':'Novo cliente'" :busy="busy" @close="emit('close')"><p v-if="loading" role="status">Carregando dados e vínculos…</p><p v-if="error" role="alert">{{ error }}</p>
    <form v-if="!loading&&ready" class="vue-form" @submit.prevent="save" @invalid.capture="tab='dados'"><p class="client-editor-intro">Confira os dados da empresa. A consulta CNPJ só preenche os campos após sua confirmação.</p><fieldset class="client-editor-fields" :disabled="busy"><nav class="registry-tabs" aria-label="Dados do cliente"><button v-for="[key,label] in [['dados','Dados e envio'],['contatos','Contatos'],['sindicatos','Sindicatos']]" :key="key" type="button" :aria-pressed="tab===key" @click="tab=key">{{ label }}</button></nav>
      <section v-show="tab==='dados'" class="vue-form client-data-grid"><label>Razão social<input v-model="form.razao_social" required minlength="2" maxlength="250"></label><label>CNPJ<input v-model="form.cnpj" required maxlength="25"></label><label>Nome fantasia<input v-model="form.nome_fantasia" maxlength="500"></label><label>UF<select v-model="form.uf"><option value="">Não informada</option><option v-for="state in states" :key="state">{{ state }}</option></select></label><label>Município<input v-model="form.municipio" maxlength="500"></label><label>Situação do cliente<select v-model="form.ativo"><option :value="true">Ativo</option><option :value="false">Inativo</option></select></label><label>Modo de envio<select v-model="form.modo_envio"><option value="revisao">Revisar antes de enviar</option><option value="automatico">Automático conforme regras</option></select></label></section>
      <CnpjLookup v-show="tab==='dados'" :cnpj="form.cnpj" :request="request" :disabled="busy" @apply="applyCnpj" />
      <section v-show="tab==='contatos'"><h3>Contatos e recebimento</h3><p class="client-editor-intro">Selecione os contatos desta empresa e defina a função e os documentos que cada um recebe.</p><p role="status">{{ form.contatos.length }} contato(s) vinculado(s)</p><p v-if="!contacts.length">Nenhum contato disponível. Cadastre em Contatos.</p><fieldset v-for="person in contacts" :key="person.id" class="instrument-types"><legend>{{ person.nome }}</legend><p class="client-editor-intro">{{ person.email||'E-mail não informado' }}</p><label><input type="checkbox" :checked="form.contatos.some(item=>item.contato_id===person.id)" @change="toggleContact(person.id,($event.target as HTMLInputElement).checked)">Vincular contato</label><div v-for="link in form.contatos.filter(item=>item.contato_id===person.id)" :key="link.contato_id" class="vue-form"><label>Função neste cliente<input v-model="link.funcao" maxlength="500"></label><label><input v-model="link.receber_email" type="checkbox">Receber documentos por e-mail</label><details><summary>Tipos de documento</summary><p>Sem seleção, recebe todos os tipos.</p><label v-for="type in types" :key="type"><input v-model="link.tipos" type="checkbox" :value="type">{{ type }}</label></details></div></fieldset></section>
      <section v-show="tab==='sindicatos'"><h3>Enquadramento sindical</h3><p class="client-editor-intro">Confira categoria e localidade de cada vínculo. Apenas um sindicato pode ser principal.</p><p role="status">{{ form.sindicatos.length }} sindicato(s) vinculado(s)</p><p v-if="!unions.length">Configure um sindicato em Cadastros → Sindicatos.</p><fieldset v-for="union in unions" :key="union.id" class="instrument-types"><legend>{{ union.nome }}</legend><label><input type="checkbox" :checked="form.sindicatos.some(item=>item.sindicato_id===union.id)" @change="toggleUnion(union.id,($event.target as HTMLInputElement).checked)">Vincular sindicato</label><div v-for="link in form.sindicatos.filter(item=>item.sindicato_id===union.id)" :key="link.sindicato_id" class="vue-form"><label>Categoria do cliente<input v-model="link.categoria" maxlength="500"></label><label>UF do enquadramento<select v-model="link.uf"><option value="">Não informada</option><option v-for="state in states" :key="state">{{ state }}</option></select></label><label>Município do enquadramento<input v-model="link.municipio" maxlength="500"></label><label><input type="radio" name="principal" :checked="link.principal" @change="principal(link.sindicato_id)">Sindicato principal</label><label><input v-model="link.enquadramento_confirmado" type="checkbox">Enquadramento conferido pelo escritório</label></div></fieldset><button type="button" class="secondary" @click="form.sindicatos.forEach(item=>item.principal=false)">Sem sindicato principal</button></section>
      </fieldset><footer><button type="button" class="secondary" :disabled="busy" @click="emit('close')">Cancelar</button><button type="submit" class="primary" :disabled="busy">{{ busy?'Salvando…':'Salvar cliente' }}</button></footer>
    </form>
  </AppDialog>
</template>

<style scoped>
.client-editor-intro{margin:0;color:var(--muted);font-size:14px}
.client-editor-fields{border:0;padding:0;margin:0;min-width:0;display:grid;gap:20px}
.client-data-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
.instrument-types{margin:18px 0;padding:18px;background:var(--bg)}
.instrument-types legend{font-weight:600;padding:0 6px;overflow-wrap:anywhere}
.instrument-types>.vue-form{margin-top:16px}.instrument-types details{padding:12px;border:1px solid var(--line);border-radius:10px}
.instrument-types .vue-form>label:has(select),.instrument-types .vue-form>label:has(input[type=text]),.instrument-types .vue-form>label:has(input:not([type])){display:grid}
.instrument-types input[type=radio]{width:18px;flex:0 0 18px;accent-color:var(--accent)}
@media(max-width:700px){.client-data-grid{grid-template-columns:minmax(0,1fr)}}
</style>
